from pathlib import Path
R=Path(__file__).resolve().parents[1]
p=R/'_shots/ship_alignment_0914';p.mkdir(parents=True,exist_ok=True)
(p/'review.html').write_text('<!DOCTYPE html>\n<html lang="en">\n<head><base href="/"><script>window.requestAnimationFrame=()=>0;</script>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width,initial-scale=1,user-scalable=no,viewport-fit=cover">\n<title>Bullets of Fury</title>\n<style>\n  /* Command Signal shares the uppercase bitmap dialogue letterforms with legacy canvas text. */\n  @font-face{ font-family:\'BOFmil\'; src:url(\'assets/game/fonts/command_0914/BOFCommandSignal.ttf\') format(\'truetype\'); font-display:swap; }\n  html,body{margin:0;padding:0;height:100%;background:#05060a;overflow:hidden;\n    font-family:"Courier New",monospace;color:#cfd6e0;-webkit-user-select:none;user-select:none;touch-action:none;}\n  /* ROOM: a simple centred row — credits, game, credits. No cabinet, no filtered ancestor. */\n  #room{position:fixed;inset:0;display:flex;align-items:center;justify-content:center;gap:clamp(10px,3vw,54px);\n    background:radial-gradient(130% 100% at 50% 12%, #181320 0%, #0b0b12 55%, #050507 100%);}\n  #stage{display:flex;flex-direction:column;align-items:center;gap:6px;}\n  #marquee{display:block;object-fit:contain;position:relative;z-index:3;filter:drop-shadow(0 5px 16px rgba(0,0,0,.6));}\n  #playrow{display:flex;flex-direction:row;align-items:center;gap:16px;position:relative;z-index:2;}\n  .side{display:block;object-fit:contain;flex:0 0 auto;filter:drop-shadow(0 6px 16px rgba(0,0,0,.55));}\n  /* black window: HUD row (HUD strip + equip box) on top, divider, native game canvas below */\n  #game-frame{position:absolute;background:#000;overflow:hidden;z-index:1;\n    display:flex;flex-direction:column;align-items:flex-start;}\n  #hud-row{display:flex;flex-direction:row;align-items:flex-start;justify-content:flex-start;flex:0 0 auto;}\n  #hud-wrap{position:relative;flex:0 0 auto;background:#000;}\n  #hud-wrap canvas{display:block;width:100%;height:100%;}\n  #equip-dom{position:relative;flex:0 0 auto;pointer-events:none;}\n  #equip-dom canvas{display:block;width:100%;height:100%;image-rendering:pixelated;}\n  #hud-div{flex:0 0 auto;width:100%;height:3px;background:#2a2d33;box-shadow:0 1px 0 #15171b;}\n  #screen-area{position:relative;flex:0 0 auto;width:100%;overflow:hidden;}\n  /* The canvas is sized in JS by fitCanvas() (aspect-locked) and CENTRED here. It used to be\n     forced to width:100%;height:100%, which stretched it to whatever shape #screen-area was and\n     made fitCanvas\'s own sizing pointless — that is why fullscreen was off-centre and distorted. */\n  /* image-rendering was `auto`, i.e. the browser bilinear-scaled the backing canvas AGAIN on the\n     way to the display — a second blur on top of the one imageSmoothingEnabled was adding. The\n     equip-box canvas below already had `pixelated`; the game canvas is the one the player looks\n     at, so it is the one that needed it. */\n  #screen-area canvas{display:block;position:absolute;left:50%;top:50%;\n    transform:translate(-50%,-50%);image-rendering:pixelated;background:#000;}\n  #hint{position:fixed;left:8px;right:8px;bottom:6px;display:flex;flex-wrap:wrap;justify-content:center;gap:12px;font-size:10px;color:#afbdce;pointer-events:none;}\n  #hint span{display:inline-flex;align-items:center;gap:5px;} #hint canvas{image-rendering:pixelated;}\n\n  /* ---- FULLSCREEN button ---- */\n  #fs-btn{position:fixed;right:12px;top:12px;z-index:50;width:40px;height:40px;\n    display:flex;align-items:center;justify-content:center;cursor:pointer;\n    background:rgba(18,24,36,0.82);border:2px solid #4a90c0;border-radius:7px;\n    color:#cfe2ff;box-shadow:0 4px 14px rgba(0,0,0,.5);transition:background .12s,border-color .12s;-webkit-user-select:none;user-select:none;}\n  #fs-btn:hover{background:#243550;border-color:#8fd0ff;}\n  #fs-btn svg{width:20px;height:20px;pointer-events:none;fill:currentColor;}\n\n  /* ---- FULLSCREEN mode: hide the cabinet art, blow the play window up to fill the screen ---- */\n  body.fs #room{background:#000;}\n  body.fs #marquee,\n  body.fs #side-left,\n  body.fs #side-right{display:none !important;}\n  body.fs #playrow{gap:0;}\n  body.fs #game-frame{border-radius:0;box-shadow:none;}\n  /* POSITION:FIXED CONTAINING-BLOCK TRAP.\n     #cabinet carries a drop-shadow filter, and ANY filtered ancestor becomes the containing block\n     for its position:fixed descendants. So #game-frame\'s fullscreen left/top were being measured\n     from the CABINET\'s box instead of the viewport — and since the cabinet is flex-centred inside\n     #room, that offset pushed the whole game across. Clearing the filter (and collapsing the\n     cabinet, which is invisible in fullscreen anyway) makes fixed mean fixed again. */\n  body.fs\n  body.fs #stage{gap:0 !important;}\n  body.fs #hint{display:none;}\n  body.fs #fs-btn{opacity:0.25;}\n  body.fs #fs-btn:hover{opacity:1;}\n\n\n  /* CREDIT RAILS. Vertical text either side of the play window. pointer-events:none so they can\n     never intercept a click meant for the canvas — the whole reason the cabinet came out. */\n  #credit-left,#credit-right{\n    pointer-events:none; user-select:none;\n    font-family:\'BOFmil\',monospace; letter-spacing:.14em; line-height:1.5;\n    font-size:clamp(9px,1.05vw,15px);\n    color:#8e9bb3; text-shadow:0 0 10px rgba(120,160,255,.22);\n    flex:0 0 auto; white-space:nowrap;\n  }\n  #credit-left{text-align:right;}\n  #credit-right{text-align:left;}\n  #credit-left .yr{color:#c9a227;}\n  #credit-right .nick{color:#c9a227;}\n  @media (max-width:820px){ #credit-left,#credit-right{display:none;} }\n  body.fs #credit-left, body.fs #credit-right{display:none;}\n  body.cinematic-full #room{background:#000;display:block;}\n  body.cinematic-full #credit-left,\n  body.cinematic-full #credit-right,\n  body.cinematic-full #hud-row,\n  body.cinematic-full #hud-div,\n  body.cinematic-full #fs-btn,\n  body.cinematic-full #hint{display:none !important;}\n  body.cinematic-full #game-frame{position:fixed !important;inset:0 !important;width:100vw !important;\n    height:100vh !important;background:#000;display:block;overflow:hidden;}\n  body.cinematic-full #screen-area{position:fixed;inset:0;width:100vw !important;height:100vh !important;\n    margin:0 !important;overflow:hidden;}\n  body.cinematic-full #screen{width:100vw !important;height:100vh !important;}\n</style>\n</head>\n<body>\n<div id="room">\n  <!-- CABINET REMOVED (drop 0724dk). The cabinet image sat above the play area with its own\n       stacking context, its own drop-shadow filter (which changes what `position:fixed` means for\n       every descendant), and a JS layout pass that repositioned #game-frame into a hard-coded\n       window rect. Mike asked for it gone; it also removes a whole class of suspects for input\n       that does not land where it looks like it should. -->\n  <div id="credit-left">COLEFORGE<br>PRODUCTIONS<br><span class="yr">2026</span></div>\n  <div id="game-frame">\n    <div id="hud-row">\n      <div id="hud-wrap"><canvas id="hud" width="480" height="62"></canvas></div>\n      <div id="equip-dom"><canvas id="equipcv" width="128" height="128"></canvas></div>\n    </div>\n    <div id="hud-div"></div>\n    <div id="screen-area"><canvas id="screen" width="480" height="512"></canvas></div>\n  </div>\n  <div id="credit-right">A GAME BY<br>MIKE<br><span class="nick">&ldquo;FORGEMASTER&rdquo;</span><br>COLE</div>\n</div>\n<div id="fs-btn" title="Fullscreen (F)" aria-label="Toggle fullscreen">\n  <svg id="fs-icon-enter" viewBox="0 0 24 24"><path d="M4 9V4h5v2H6v3H4zm0 6h2v3h3v2H4v-5zm16 0v5h-5v-2h3v-3h2zM20 9h-2V6h-3V4h5v5z"/></svg>\n  <svg id="fs-icon-exit" viewBox="0 0 24 24" style="display:none"><path d="M9 4v5H4V7h3V4h2zm11 3v2h-5V4h2v3h3zM9 20H7v-3H4v-2h5v5zm11-5v2h-3v3h-2v-5h5z"/></svg>\n</div>\n<div id="hint" aria-label="Game controls"></div>\n<script>\n(function(){\n  // OUT-OF-BOUNDS EQUIPPED box: renders the current weapon pickup icon in the box art,\n  // to the right of the game screen. Hidden when no weapon / player dead.\n  var cv=document.getElementById(\'equipcv\'); if(!cv) return;\n  var g=cv.getContext(\'2d\'); g.imageSmoothingEnabled=false;\n  var WT={0:\'mg\',1:\'spread\',2:\'missile\',3:\'laser\',4:\'firewall\',5:\'iceorb\',6:\'lasermist\'};\n  window.__drawEquipDom=function(px){\n    var W=cv.width, H=cv.height; g.clearRect(0,0,W,H);\n    /* GAMEPLAY ONLY (drop 0809p). The box was drawn in every state, so the boot logo, the\n       arcade attract reel and the pilot select all carried an EQUIPPED panel hanging over\n       them. It belongs to the run, not to the app. Cleared above, so hiding is simply\n       returning early. */\n    /* ⚠ NOT window.state. game.js declares it with `let` at top level, which creates a LEXICAL\n       global - reachable as a bare identifier from another classic script, but never a property\n       of window. Reading window.state gives undefined and would hide the box in every state,\n       including gameplay. */\n    var st = null;\n    try { st = state; } catch(e) { st = null; }\n    if(st !== null &&\n       !(st===\'play\' || st===\'paused\' || st===\'stageclear\' || st===\'continue\' || st===\'gameover\')) return;\n    var X=(window.XART||null);\n    if(!X || !X.rdy || !X.rdy(\'nequipbox\')) return;\n    var box=X.get(\'nequipbox\');\n    g.drawImage(box,0,0,W,H);\n    try{\n      var run=window.run;\n      if(run && !window.player.dead && run.weapon!=null){\n        var wt=WT[run.weapon]||\'mg\';\n        var wlv=Math.max(1,Math.min(5,(run.wlevels&&run.wlevels[run.weapon])||run.wlevel||1));\n        /* ⚠ THE PRECEDING COMMENT WAS WRONG AND IT COST MIKE THE RIGHT ICON (fixed 0810s).\n           micon_* DOES exist — as 57 rects in BOFX.icons, the THIRD art store, which XART can\n           never answer for. So `X.rdy(\'micon_...\')` was false for every weapon on every frame,\n           the micon_ candidate always lost, and this quietly drew the older *_icon_* set. That\n           is "I see your using a basic graphic for fireball icon".\n\n           And WT above is a second weapon table: it hard-codes 5:\'iceorb\', so slot 5 could never\n           show the fireball no matter which store answered. weaponIconKey is the game\'s own\n           resolver and already knows stage 3 dispenses the fireball and that Freezer\'s is the\n           fire/ice ball (0806d). Ask IT, and blit through the shared iconBlit so this surface and\n           the in-game one cannot drift apart again. The old chain stays as the fallback. */\n        var cx=W*0.499, cy=H*0.505, drew=null;\n        var ik = null;\n        try { ik = weaponIconKey(run.weapon, wlv); } catch(e){ ik = \'micon_\'+wt+\'_\'+wlv; }\n        g.save(); g.shadowColor=\'#ffb24a\'; g.shadowBlur=6;\n        try { if(typeof iconBlit===\'function\') drew = iconBlit(g, ik, cx, cy, H*0.56, true); }\n        catch(e){ drew = null; }\n        if(drew==null){\n          var alt = (wt===\'iceorb\') ? \'ice\' : wt;\n          var cands = [alt+\'_icon_\'+wlv, alt+\'_icon_1\', alt+\'_icon\'];\n          for(var ci=0; ci<cands.length; ci++){ if(X.rdy(cands[ci])){ ik = cands[ci]; break; } }\n          if(ik && X.rdy(ik)){\n            var im=X.get(ik), fit=W*0.52, ss=Math.min(fit/im.naturalWidth, fit/im.naturalHeight);\n            g.drawImage(im, cx-im.naturalWidth*ss/2, cy-im.naturalHeight*ss/2,\n                        im.naturalWidth*ss, im.naturalHeight*ss);\n          }\n        }\n        g.restore();\n      }\n    }catch(e){}\n  };\n  // redraw each frame so the icon follows weapon changes / death\n  function tick(){ if(window.__drawEquipDom) window.__drawEquipDom(); requestAnimationFrame(tick); }\n  requestAnimationFrame(tick);\n})();\n</script>\n<script src="assets/manifest.js"></script>\n<script src="assets/stagefonts_v4.js"></script>\n<script src="assets/game/fonts/bmf_maps.js"></script>\n<script src="assets/game/fonts/command_0914/fonts.js"></script>\n<!-- Measured section geometry for the eight 0801hm miniboss bodies (window.BOFSG).\n     Must load BEFORE game.js: sxDraw composites the body from its section plates\n     using these offsets, and sxHit attributes shots with these centroids. -->\n<script src="assets/section_geom.js"></script>\n<!-- Gravity Mode atlas metadata is a classic script so direct file:// play works too; fetch()\n     cannot read a neighbouring JSON file in that mode. The texture itself is still one atlas. -->\n<script src="assets/game/atlas/bof_gravity_mode_space_weapons.js"></script>\n<script src="assets/game/atlas/stage_runtime_atlases.js"></script>\n<script src="assets/game/atlas/stage5_runtime_atlas.js"></script>\n<script src="assets/game.js?alignment=0914v1"></script>\n<script>\n(function(){\n  var GA=480/512, SIDE_A=335/1042, MARQ_A=693/179, HUD_R=62/512, gap=16, FR=14, mgap=6, MSCALE=1.12;\n  function isFS(){ return document.body.classList.contains(\'fs\'); }\n  /* LAYOUT WITHOUT THE CABINET (drop 0724dk).\n     The old version mapped the play area into a hard-coded window rect inside the cabinet image\n     (WIN_L/T/R/B as fractions of a 1448x1086 plate) and positioned #game-frame absolutely into it.\n     That is gone. The room is now a plain flex row and the play window is simply sized to fit the\n     viewport at the game\'s own aspect, so what you click is where it looks. */\n  var GW=480, GH=512, HUDH=62, DIVH=6;\n  function fit(){\n    var vw=innerWidth, vh=innerHeight;\n    function S(id,w,h){ var e=document.getElementById(id); if(e){ e.style.width=w+\'px\'; e.style.height=h+\'px\'; } }\n    if(document.body.classList.contains(\'cinematic-full\')){\n      var gf0=document.getElementById(\'game-frame\'),sa0=document.getElementById(\'screen-area\'),scr0=document.getElementById(\'screen\');\n      if(gf0){gf0.style.position=\'fixed\';gf0.style.left=\'0px\';gf0.style.top=\'0px\';gf0.style.width=vw+\'px\';gf0.style.height=vh+\'px\';}\n      if(sa0){sa0.style.width=vw+\'px\';sa0.style.height=vh+\'px\';sa0.style.marginLeft=\'0px\';}\n      if(scr0){scr0.style.width=vw+\'px\';scr0.style.height=vh+\'px\';}\n      return;\n    }\n    var reserve = isFS() ? 0 : Math.min(vw*0.34, 420);      // room for the credit rails\n    var availW = Math.max(200, vw - reserve);\n    var availH = vh * (isFS()? 1.0 : 0.94);\n    var totalH = GH + HUDH + DIVH;\n    var sc = Math.min(availW/GW, availH/totalH);\n    var gw = Math.round(GW*sc), gh = Math.round(GH*sc);\n    var hh = Math.round(HUDH*sc), dh = Math.round(DIVH*sc);\n    var gf=document.getElementById(\'game-frame\');\n    if(gf){ gf.style.position=\'relative\'; gf.style.left=\'0px\'; gf.style.top=\'0px\'; }\n    S(\'game-frame\', gw, gh+hh+dh);\n    S(\'hud-row\', gw, hh); S(\'hud-wrap\', gw, hh);\n    S(\'hud-div\', gw, dh);\n    S(\'screen-area\', gw, gh);\n    var sa=document.getElementById(\'screen-area\'); if(sa) sa.style.marginLeft=\'0px\';\n    var scr=document.getElementById(\'screen\'); if(scr){ scr.style.width=gw+\'px\'; scr.style.height=gh+\'px\'; }\n    var hud=document.getElementById(\'hud\');     if(hud){ hud.style.width=gw+\'px\';  hud.style.height=hh+\'px\'; }\n  }\n  /* The old layout function was named L and the listeners still referenced it; my replacement is\n     fit(). Aliasing keeps every existing call site working instead of hunting them all. */\n  var L = fit;\n  window.__bofFit=fit;\n  window.addEventListener(\'resize\',L); window.addEventListener(\'load\',L);\n  fit();\n\n  // ---- FULLSCREEN toggle ----\n  var root=document.getElementById(\'room\');\n  function fsElement(){ return document.getElementById(\'room\'); }\n  function inNativeFS(){ return !!(document.fullscreenElement||document.webkitFullscreenElement||document.mozFullScreenElement||document.msFullscreenElement); }\n  function requestFS(el){\n    if(el.requestFullscreen) return el.requestFullscreen();\n    if(el.webkitRequestFullscreen) return el.webkitRequestFullscreen();\n    if(el.mozRequestFullScreen) return el.mozRequestFullScreen();\n    if(el.msRequestFullscreen) return el.msRequestFullscreen();\n  }\n  function exitFS(){\n    if(document.exitFullscreen) return document.exitFullscreen();\n    if(document.webkitExitFullscreen) return document.webkitExitFullscreen();\n    if(document.mozCancelFullScreen) return document.mozCancelFullScreen();\n    if(document.msExitFullscreen) return document.msExitFullscreen();\n  }\n  function toggleFS(){\n    if(inNativeFS()){ exitFS(); }\n    else { try{ var p=requestFS(fsElement()); if(p&&p.catch) p.catch(function(){ /* fallback: CSS-only fill */ document.body.classList.add(\'fs\'); syncFSicon(); L(); }); }catch(e){ document.body.classList.add(\'fs\'); } }\n  }\n  function syncFSicon(){\n    var on=document.body.classList.contains(\'fs\');\n    var a=document.getElementById(\'fs-icon-enter\'), b=document.getElementById(\'fs-icon-exit\');\n    if(a) a.style.display=on?\'none\':\'block\';\n    if(b) b.style.display=on?\'block\':\'none\';\n  }\n  function onFSchange(){\n    if(inNativeFS()) document.body.classList.add(\'fs\'); else document.body.classList.remove(\'fs\');\n    syncFSicon(); L(); setTimeout(L,50);\n  }\n  document.addEventListener(\'fullscreenchange\',onFSchange);\n  document.addEventListener(\'webkitfullscreenchange\',onFSchange);\n  document.addEventListener(\'mozfullscreenchange\',onFSchange);\n  document.addEventListener(\'MSFullscreenChange\',onFSchange);\n  var fsBtn=document.getElementById(\'fs-btn\');\n  if(fsBtn) fsBtn.addEventListener(\'click\',function(e){ e.preventDefault(); e.stopPropagation(); toggleFS(); });\n  // F key toggles fullscreen (ignored while typing a password, handled by game input otherwise)\n  window.addEventListener(\'keydown\',function(e){\n    if((e.key===\'f\'||e.key===\'F\') && !e.ctrlKey && !e.metaKey && !e.altKey){\n      var st=(window.BOFGAME&&window.BOFGAME.state)||\'\';\n      // don\'t hijack F if a text field is focused\n      var ae=document.activeElement; if(ae&&(ae.tagName===\'INPUT\'||ae.tagName===\'TEXTAREA\')) return;\n      e.preventDefault(); toggleFS();\n    }\n  });\n  window.fsToggle=toggleFS;\n\n  L(); setTimeout(L,60); setTimeout(L,300);\n})();\n</script>\n<div style="position:fixed;inset:0;overflow:auto;z-index:999999;background:#18202c;color:white;font:14px monospace"><button id="inspect">Inspect rotation frames</button><button id="onion">Onion review</button><canvas style="display:block;width:700px;height:700px" id="sheet" width="1000" height="1000"></canvas><pre id="metrics"></pre></div><script>\ndocument.querySelector(\'#inspect\').onclick=()=>{let rows=[],c=document.querySelector(\'#sheet\').getContext(\'2d\');c.clearRect(0,0,1000,1000);let pilots=[\'axel\',\'decker\',\'cole\',\'falva\',\'lizzie\',\'maverick\',\'yuri\',\'vex\',\'kane\'];let keys=Object.keys(BOFX.ships).filter(k=>/^ship_.*_br0$/.test(k));pilots=keys.map(k=>k.slice(5,-4));pilots.forEach((p,j)=>{c.fillStyle=\'white\';c.fillText(p,0,j*100+12);for(let i=0;i<8;i++){let k=\'ship_\'+p+\'_br\'+i;if(!XART.rdy(k))continue;let im=XART.get(k),a=document.createElement(\'canvas\');a.width=im.width;a.height=im.height;let g=a.getContext(\'2d\');g.drawImage(im,0,0);let d=g.getImageData(0,0,a.width,a.height).data,x0=a.width,y0=a.height,x1=-1,y1=-1;for(let y=0;y<a.height;y++)for(let x=0;x<a.width;x++)if(d[(y*a.width+x)*4+3]>24){x0=Math.min(x0,x);y0=Math.min(y0,y);x1=Math.max(x1,x);y1=Math.max(y1,y);}rows.push({p,i,w:a.width,h:a.height,x0,y0,x1,y1});let place=psShipPlacement(k,im,90,82);rows[rows.length-1].placement=place;let sc=place.scale;c.strokeStyle=\'#39495b\';c.strokeRect(100+i*110,j*100+15,90,82);c.drawImage(im,145+i*110-place.x*sc,j*100+56-place.y*sc,a.width*sc,a.height*sc);}});document.querySelector(\'#metrics\').textContent=JSON.stringify(rows);};\ndocument.querySelector(\'#onion\').onclick=()=>{const g=document.querySelector(\'#sheet\').getContext(\'2d\');g.clearRect(0,0,1000,1000);const pilots=Object.keys(BOFX.ships).filter(k=>/^ship_.*_br0$/.test(k)).map(k=>k.slice(5,-4));pilots.forEach((p,j)=>{const ox=(j%3)*330,oy=Math.floor(j/3)*310;g.fillStyle=\'white\';g.fillText(p+\' / before / centered\',ox+8,oy+15);for(let mode=0;mode<2;mode++){const cx=ox+80+mode*155,cy=oy+150;g.strokeStyle=\'#71869c\';g.strokeRect(cx-70,cy-110,140,220);g.beginPath();g.moveTo(cx,cy-110);g.lineTo(cx,cy+110);g.moveTo(cx-70,cy);g.lineTo(cx+70,cy);g.stroke();for(let i=0;i<8;i++){let k=\'ship_\'+p+\'_br\'+i;if(!XART.rdy(k))continue;let im=XART.get(k),place=psShipPlacement(k,im,130,200),sc=place.scale;g.globalAlpha=.22;g.drawImage(im,cx-(mode?place.x:im.width/2)*sc,cy-(mode?place.y:im.height/2)*sc,im.width*sc,im.height*sc);g.globalAlpha=1;}}});};</script></body>\n</html>\n',encoding='utf-8')
(p/'menu.html').write_text('<!DOCTYPE html>\n<html lang="en">\n<head><base href="/"><script>window.requestAnimationFrame=()=>0;</script>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width,initial-scale=1,user-scalable=no,viewport-fit=cover">\n<title>Bullets of Fury</title>\n<style>\n  /* Command Signal shares the uppercase bitmap dialogue letterforms with legacy canvas text. */\n  @font-face{ font-family:\'BOFmil\'; src:url(\'assets/game/fonts/command_0914/BOFCommandSignal.ttf\') format(\'truetype\'); font-display:swap; }\n  html,body{margin:0;padding:0;height:100%;background:#05060a;overflow:hidden;\n    font-family:"Courier New",monospace;color:#cfd6e0;-webkit-user-select:none;user-select:none;touch-action:none;}\n  /* ROOM: a simple centred row — credits, game, credits. No cabinet, no filtered ancestor. */\n  #room{position:fixed;inset:0;display:flex;align-items:center;justify-content:center;gap:clamp(10px,3vw,54px);\n    background:radial-gradient(130% 100% at 50% 12%, #181320 0%, #0b0b12 55%, #050507 100%);}\n  #stage{display:flex;flex-direction:column;align-items:center;gap:6px;}\n  #marquee{display:block;object-fit:contain;position:relative;z-index:3;filter:drop-shadow(0 5px 16px rgba(0,0,0,.6));}\n  #playrow{display:flex;flex-direction:row;align-items:center;gap:16px;position:relative;z-index:2;}\n  .side{display:block;object-fit:contain;flex:0 0 auto;filter:drop-shadow(0 6px 16px rgba(0,0,0,.55));}\n  /* black window: HUD row (HUD strip + equip box) on top, divider, native game canvas below */\n  #game-frame{position:absolute;background:#000;overflow:hidden;z-index:1;\n    display:flex;flex-direction:column;align-items:flex-start;}\n  #hud-row{display:flex;flex-direction:row;align-items:flex-start;justify-content:flex-start;flex:0 0 auto;}\n  #hud-wrap{position:relative;flex:0 0 auto;background:#000;}\n  #hud-wrap canvas{display:block;width:100%;height:100%;}\n  #equip-dom{position:relative;flex:0 0 auto;pointer-events:none;}\n  #equip-dom canvas{display:block;width:100%;height:100%;image-rendering:pixelated;}\n  #hud-div{flex:0 0 auto;width:100%;height:3px;background:#2a2d33;box-shadow:0 1px 0 #15171b;}\n  #screen-area{position:relative;flex:0 0 auto;width:100%;overflow:hidden;}\n  /* The canvas is sized in JS by fitCanvas() (aspect-locked) and CENTRED here. It used to be\n     forced to width:100%;height:100%, which stretched it to whatever shape #screen-area was and\n     made fitCanvas\'s own sizing pointless — that is why fullscreen was off-centre and distorted. */\n  /* image-rendering was `auto`, i.e. the browser bilinear-scaled the backing canvas AGAIN on the\n     way to the display — a second blur on top of the one imageSmoothingEnabled was adding. The\n     equip-box canvas below already had `pixelated`; the game canvas is the one the player looks\n     at, so it is the one that needed it. */\n  #screen-area canvas{display:block;position:absolute;left:50%;top:50%;\n    transform:translate(-50%,-50%);image-rendering:pixelated;background:#000;}\n  #hint{position:fixed;left:8px;right:8px;bottom:6px;display:flex;flex-wrap:wrap;justify-content:center;gap:12px;font-size:10px;color:#afbdce;pointer-events:none;}\n  #hint span{display:inline-flex;align-items:center;gap:5px;} #hint canvas{image-rendering:pixelated;}\n\n  /* ---- FULLSCREEN button ---- */\n  #fs-btn{position:fixed;right:12px;top:12px;z-index:50;width:40px;height:40px;\n    display:flex;align-items:center;justify-content:center;cursor:pointer;\n    background:rgba(18,24,36,0.82);border:2px solid #4a90c0;border-radius:7px;\n    color:#cfe2ff;box-shadow:0 4px 14px rgba(0,0,0,.5);transition:background .12s,border-color .12s;-webkit-user-select:none;user-select:none;}\n  #fs-btn:hover{background:#243550;border-color:#8fd0ff;}\n  #fs-btn svg{width:20px;height:20px;pointer-events:none;fill:currentColor;}\n\n  /* ---- FULLSCREEN mode: hide the cabinet art, blow the play window up to fill the screen ---- */\n  body.fs #room{background:#000;}\n  body.fs #marquee,\n  body.fs #side-left,\n  body.fs #side-right{display:none !important;}\n  body.fs #playrow{gap:0;}\n  body.fs #game-frame{border-radius:0;box-shadow:none;}\n  /* POSITION:FIXED CONTAINING-BLOCK TRAP.\n     #cabinet carries a drop-shadow filter, and ANY filtered ancestor becomes the containing block\n     for its position:fixed descendants. So #game-frame\'s fullscreen left/top were being measured\n     from the CABINET\'s box instead of the viewport — and since the cabinet is flex-centred inside\n     #room, that offset pushed the whole game across. Clearing the filter (and collapsing the\n     cabinet, which is invisible in fullscreen anyway) makes fixed mean fixed again. */\n  body.fs\n  body.fs #stage{gap:0 !important;}\n  body.fs #hint{display:none;}\n  body.fs #fs-btn{opacity:0.25;}\n  body.fs #fs-btn:hover{opacity:1;}\n\n\n  /* CREDIT RAILS. Vertical text either side of the play window. pointer-events:none so they can\n     never intercept a click meant for the canvas — the whole reason the cabinet came out. */\n  #credit-left,#credit-right{\n    pointer-events:none; user-select:none;\n    font-family:\'BOFmil\',monospace; letter-spacing:.14em; line-height:1.5;\n    font-size:clamp(9px,1.05vw,15px);\n    color:#8e9bb3; text-shadow:0 0 10px rgba(120,160,255,.22);\n    flex:0 0 auto; white-space:nowrap;\n  }\n  #credit-left{text-align:right;}\n  #credit-right{text-align:left;}\n  #credit-left .yr{color:#c9a227;}\n  #credit-right .nick{color:#c9a227;}\n  @media (max-width:820px){ #credit-left,#credit-right{display:none;} }\n  body.fs #credit-left, body.fs #credit-right{display:none;}\n  body.cinematic-full #room{background:#000;display:block;}\n  body.cinematic-full #credit-left,\n  body.cinematic-full #credit-right,\n  body.cinematic-full #hud-row,\n  body.cinematic-full #hud-div,\n  body.cinematic-full #fs-btn,\n  body.cinematic-full #hint{display:none !important;}\n  body.cinematic-full #game-frame{position:fixed !important;inset:0 !important;width:100vw !important;\n    height:100vh !important;background:#000;display:block;overflow:hidden;}\n  body.cinematic-full #screen-area{position:fixed;inset:0;width:100vw !important;height:100vh !important;\n    margin:0 !important;overflow:hidden;}\n  body.cinematic-full #screen{width:100vw !important;height:100vh !important;}\n</style>\n</head>\n<body>\n<div id="room">\n  <!-- CABINET REMOVED (drop 0724dk). The cabinet image sat above the play area with its own\n       stacking context, its own drop-shadow filter (which changes what `position:fixed` means for\n       every descendant), and a JS layout pass that repositioned #game-frame into a hard-coded\n       window rect. Mike asked for it gone; it also removes a whole class of suspects for input\n       that does not land where it looks like it should. -->\n  <div id="credit-left">COLEFORGE<br>PRODUCTIONS<br><span class="yr">2026</span></div>\n  <div id="game-frame">\n    <div id="hud-row">\n      <div id="hud-wrap"><canvas id="hud" width="480" height="62"></canvas></div>\n      <div id="equip-dom"><canvas id="equipcv" width="128" height="128"></canvas></div>\n    </div>\n    <div id="hud-div"></div>\n    <div id="screen-area"><canvas id="screen" width="480" height="512"></canvas></div>\n  </div>\n  <div id="credit-right">A GAME BY<br>MIKE<br><span class="nick">&ldquo;FORGEMASTER&rdquo;</span><br>COLE</div>\n</div>\n<div id="fs-btn" title="Fullscreen (F)" aria-label="Toggle fullscreen">\n  <svg id="fs-icon-enter" viewBox="0 0 24 24"><path d="M4 9V4h5v2H6v3H4zm0 6h2v3h3v2H4v-5zm16 0v5h-5v-2h3v-3h2zM20 9h-2V6h-3V4h5v5z"/></svg>\n  <svg id="fs-icon-exit" viewBox="0 0 24 24" style="display:none"><path d="M9 4v5H4V7h3V4h2zm11 3v2h-5V4h2v3h3zM9 20H7v-3H4v-2h5v5zm11-5v2h-3v3h-2v-5h5z"/></svg>\n</div>\n<div id="hint" aria-label="Game controls"></div>\n<script>\n(function(){\n  // OUT-OF-BOUNDS EQUIPPED box: renders the current weapon pickup icon in the box art,\n  // to the right of the game screen. Hidden when no weapon / player dead.\n  var cv=document.getElementById(\'equipcv\'); if(!cv) return;\n  var g=cv.getContext(\'2d\'); g.imageSmoothingEnabled=false;\n  var WT={0:\'mg\',1:\'spread\',2:\'missile\',3:\'laser\',4:\'firewall\',5:\'iceorb\',6:\'lasermist\'};\n  window.__drawEquipDom=function(px){\n    var W=cv.width, H=cv.height; g.clearRect(0,0,W,H);\n    /* GAMEPLAY ONLY (drop 0809p). The box was drawn in every state, so the boot logo, the\n       arcade attract reel and the pilot select all carried an EQUIPPED panel hanging over\n       them. It belongs to the run, not to the app. Cleared above, so hiding is simply\n       returning early. */\n    /* ⚠ NOT window.state. game.js declares it with `let` at top level, which creates a LEXICAL\n       global - reachable as a bare identifier from another classic script, but never a property\n       of window. Reading window.state gives undefined and would hide the box in every state,\n       including gameplay. */\n    var st = null;\n    try { st = state; } catch(e) { st = null; }\n    if(st !== null &&\n       !(st===\'play\' || st===\'paused\' || st===\'stageclear\' || st===\'continue\' || st===\'gameover\')) return;\n    var X=(window.XART||null);\n    if(!X || !X.rdy || !X.rdy(\'nequipbox\')) return;\n    var box=X.get(\'nequipbox\');\n    g.drawImage(box,0,0,W,H);\n    try{\n      var run=window.run;\n      if(run && !window.player.dead && run.weapon!=null){\n        var wt=WT[run.weapon]||\'mg\';\n        var wlv=Math.max(1,Math.min(5,(run.wlevels&&run.wlevels[run.weapon])||run.wlevel||1));\n        /* ⚠ THE PRECEDING COMMENT WAS WRONG AND IT COST MIKE THE RIGHT ICON (fixed 0810s).\n           micon_* DOES exist — as 57 rects in BOFX.icons, the THIRD art store, which XART can\n           never answer for. So `X.rdy(\'micon_...\')` was false for every weapon on every frame,\n           the micon_ candidate always lost, and this quietly drew the older *_icon_* set. That\n           is "I see your using a basic graphic for fireball icon".\n\n           And WT above is a second weapon table: it hard-codes 5:\'iceorb\', so slot 5 could never\n           show the fireball no matter which store answered. weaponIconKey is the game\'s own\n           resolver and already knows stage 3 dispenses the fireball and that Freezer\'s is the\n           fire/ice ball (0806d). Ask IT, and blit through the shared iconBlit so this surface and\n           the in-game one cannot drift apart again. The old chain stays as the fallback. */\n        var cx=W*0.499, cy=H*0.505, drew=null;\n        var ik = null;\n        try { ik = weaponIconKey(run.weapon, wlv); } catch(e){ ik = \'micon_\'+wt+\'_\'+wlv; }\n        g.save(); g.shadowColor=\'#ffb24a\'; g.shadowBlur=6;\n        try { if(typeof iconBlit===\'function\') drew = iconBlit(g, ik, cx, cy, H*0.56, true); }\n        catch(e){ drew = null; }\n        if(drew==null){\n          var alt = (wt===\'iceorb\') ? \'ice\' : wt;\n          var cands = [alt+\'_icon_\'+wlv, alt+\'_icon_1\', alt+\'_icon\'];\n          for(var ci=0; ci<cands.length; ci++){ if(X.rdy(cands[ci])){ ik = cands[ci]; break; } }\n          if(ik && X.rdy(ik)){\n            var im=X.get(ik), fit=W*0.52, ss=Math.min(fit/im.naturalWidth, fit/im.naturalHeight);\n            g.drawImage(im, cx-im.naturalWidth*ss/2, cy-im.naturalHeight*ss/2,\n                        im.naturalWidth*ss, im.naturalHeight*ss);\n          }\n        }\n        g.restore();\n      }\n    }catch(e){}\n  };\n  // redraw each frame so the icon follows weapon changes / death\n  function tick(){ if(window.__drawEquipDom) window.__drawEquipDom(); requestAnimationFrame(tick); }\n  requestAnimationFrame(tick);\n})();\n</script>\n<script src="assets/manifest.js"></script>\n<script src="assets/stagefonts_v4.js"></script>\n<script src="assets/game/fonts/bmf_maps.js"></script>\n<script src="assets/game/fonts/command_0914/fonts.js"></script>\n<!-- Measured section geometry for the eight 0801hm miniboss bodies (window.BOFSG).\n     Must load BEFORE game.js: sxDraw composites the body from its section plates\n     using these offsets, and sxHit attributes shots with these centroids. -->\n<script src="assets/section_geom.js"></script>\n<!-- Gravity Mode atlas metadata is a classic script so direct file:// play works too; fetch()\n     cannot read a neighbouring JSON file in that mode. The texture itself is still one atlas. -->\n<script src="assets/game/atlas/bof_gravity_mode_space_weapons.js"></script>\n<script src="assets/game/atlas/stage_runtime_atlases.js"></script>\n<script src="assets/game/atlas/stage5_runtime_atlas.js"></script>\n<script src="assets/game.js?alignment=0914v1"></script>\n<script>\n(function(){\n  var GA=480/512, SIDE_A=335/1042, MARQ_A=693/179, HUD_R=62/512, gap=16, FR=14, mgap=6, MSCALE=1.12;\n  function isFS(){ return document.body.classList.contains(\'fs\'); }\n  /* LAYOUT WITHOUT THE CABINET (drop 0724dk).\n     The old version mapped the play area into a hard-coded window rect inside the cabinet image\n     (WIN_L/T/R/B as fractions of a 1448x1086 plate) and positioned #game-frame absolutely into it.\n     That is gone. The room is now a plain flex row and the play window is simply sized to fit the\n     viewport at the game\'s own aspect, so what you click is where it looks. */\n  var GW=480, GH=512, HUDH=62, DIVH=6;\n  function fit(){\n    var vw=innerWidth, vh=innerHeight;\n    function S(id,w,h){ var e=document.getElementById(id); if(e){ e.style.width=w+\'px\'; e.style.height=h+\'px\'; } }\n    if(document.body.classList.contains(\'cinematic-full\')){\n      var gf0=document.getElementById(\'game-frame\'),sa0=document.getElementById(\'screen-area\'),scr0=document.getElementById(\'screen\');\n      if(gf0){gf0.style.position=\'fixed\';gf0.style.left=\'0px\';gf0.style.top=\'0px\';gf0.style.width=vw+\'px\';gf0.style.height=vh+\'px\';}\n      if(sa0){sa0.style.width=vw+\'px\';sa0.style.height=vh+\'px\';sa0.style.marginLeft=\'0px\';}\n      if(scr0){scr0.style.width=vw+\'px\';scr0.style.height=vh+\'px\';}\n      return;\n    }\n    var reserve = isFS() ? 0 : Math.min(vw*0.34, 420);      // room for the credit rails\n    var availW = Math.max(200, vw - reserve);\n    var availH = vh * (isFS()? 1.0 : 0.94);\n    var totalH = GH + HUDH + DIVH;\n    var sc = Math.min(availW/GW, availH/totalH);\n    var gw = Math.round(GW*sc), gh = Math.round(GH*sc);\n    var hh = Math.round(HUDH*sc), dh = Math.round(DIVH*sc);\n    var gf=document.getElementById(\'game-frame\');\n    if(gf){ gf.style.position=\'relative\'; gf.style.left=\'0px\'; gf.style.top=\'0px\'; }\n    S(\'game-frame\', gw, gh+hh+dh);\n    S(\'hud-row\', gw, hh); S(\'hud-wrap\', gw, hh);\n    S(\'hud-div\', gw, dh);\n    S(\'screen-area\', gw, gh);\n    var sa=document.getElementById(\'screen-area\'); if(sa) sa.style.marginLeft=\'0px\';\n    var scr=document.getElementById(\'screen\'); if(scr){ scr.style.width=gw+\'px\'; scr.style.height=gh+\'px\'; }\n    var hud=document.getElementById(\'hud\');     if(hud){ hud.style.width=gw+\'px\';  hud.style.height=hh+\'px\'; }\n  }\n  /* The old layout function was named L and the listeners still referenced it; my replacement is\n     fit(). Aliasing keeps every existing call site working instead of hunting them all. */\n  var L = fit;\n  window.__bofFit=fit;\n  window.addEventListener(\'resize\',L); window.addEventListener(\'load\',L);\n  fit();\n\n  // ---- FULLSCREEN toggle ----\n  var root=document.getElementById(\'room\');\n  function fsElement(){ return document.getElementById(\'room\'); }\n  function inNativeFS(){ return !!(document.fullscreenElement||document.webkitFullscreenElement||document.mozFullScreenElement||document.msFullscreenElement); }\n  function requestFS(el){\n    if(el.requestFullscreen) return el.requestFullscreen();\n    if(el.webkitRequestFullscreen) return el.webkitRequestFullscreen();\n    if(el.mozRequestFullScreen) return el.mozRequestFullScreen();\n    if(el.msRequestFullscreen) return el.msRequestFullscreen();\n  }\n  function exitFS(){\n    if(document.exitFullscreen) return document.exitFullscreen();\n    if(document.webkitExitFullscreen) return document.webkitExitFullscreen();\n    if(document.mozCancelFullScreen) return document.mozCancelFullScreen();\n    if(document.msExitFullscreen) return document.msExitFullscreen();\n  }\n  function toggleFS(){\n    if(inNativeFS()){ exitFS(); }\n    else { try{ var p=requestFS(fsElement()); if(p&&p.catch) p.catch(function(){ /* fallback: CSS-only fill */ document.body.classList.add(\'fs\'); syncFSicon(); L(); }); }catch(e){ document.body.classList.add(\'fs\'); } }\n  }\n  function syncFSicon(){\n    var on=document.body.classList.contains(\'fs\');\n    var a=document.getElementById(\'fs-icon-enter\'), b=document.getElementById(\'fs-icon-exit\');\n    if(a) a.style.display=on?\'none\':\'block\';\n    if(b) b.style.display=on?\'block\':\'none\';\n  }\n  function onFSchange(){\n    if(inNativeFS()) document.body.classList.add(\'fs\'); else document.body.classList.remove(\'fs\');\n    syncFSicon(); L(); setTimeout(L,50);\n  }\n  document.addEventListener(\'fullscreenchange\',onFSchange);\n  document.addEventListener(\'webkitfullscreenchange\',onFSchange);\n  document.addEventListener(\'mozfullscreenchange\',onFSchange);\n  document.addEventListener(\'MSFullscreenChange\',onFSchange);\n  var fsBtn=document.getElementById(\'fs-btn\');\n  if(fsBtn) fsBtn.addEventListener(\'click\',function(e){ e.preventDefault(); e.stopPropagation(); toggleFS(); });\n  // F key toggles fullscreen (ignored while typing a password, handled by game input otherwise)\n  window.addEventListener(\'keydown\',function(e){\n    if((e.key===\'f\'||e.key===\'F\') && !e.ctrlKey && !e.metaKey && !e.altKey){\n      var st=(window.BOFGAME&&window.BOFGAME.state)||\'\';\n      // don\'t hijack F if a text field is focused\n      var ae=document.activeElement; if(ae&&(ae.tagName===\'INPUT\'||ae.tagName===\'TEXTAREA\')) return;\n      e.preventDefault(); toggleFS();\n    }\n  });\n  window.fsToggle=toggleFS;\n\n  L(); setTimeout(L,60); setTimeout(L,300);\n})();\n</script>\n<div style="position:fixed;left:0;top:0;z-index:99999;background:#142034;color:white;font:11px monospace;padding:6px;width:180px;max-height:80px;overflow:auto;opacity:.18">\n<b>Authored controls / real renderer</b><br><select id="qaScreen"></select>\n<button id="qaDraw">Render</button><button id="qaSpin">Spin frame</button><button id="qaNext">Next pilot</button><button id="qaB">B</button><button id="qaDelete">Backspace</button><pre id="qaState"></pre></div>\n<script>\nconst sel=document.getElementById(\'qaScreen\');\nfor(const name of [\'PILOT\',\'TITLE\',\'MODESEL\',\'DIFF\',\'OPTIONS\',\'HELP\',\'PASSWORD\',\'CREDITS\',\'CAMPHUB\',\'BOOT\']){const o=document.createElement(\'option\');o.value=name;o.textContent=name;sel.append(o);}\nfunction qaReport(){document.getElementById(\'qaState\').textContent=JSON.stringify({state,back:\'B action\',backspace:\'delete text only\',pilot:PILOTS[pilotIndex].key,viewport:pilotViewSize(),backing:[cv.width,cv.height],fullscreen:document.body.classList.contains(\'cinematic-full\'),rect:cv.getBoundingClientRect().toJSON(),roster:psLineupRects,pixel:Array.from(ctx.getImageData(400,300,1,1).data),alpha:ctx.globalAlpha,transform:ctx.getTransform().toString()},null,1);}\nfunction qaDraw(){loop(last+1000/60);qaReport();}\nfunction qaReset(){Input.clearTaps();run.mode=\'arcade\';campPick=null;campHubIndex=0;pilotIndex=0;pilotFrom=0;pilotRot=0;pilotPending=null;pilotComm=null;setState(GS[sel.value]);stateT=2;drawPilot._entered=false;drawPilot._pcFor=null;pilotInputArmed=true;rebindAction=null;optSnap=null;helpPage=0;drawPassword.typing=false;qaDraw();if(pcard)pcSkip();qaDraw();}\ndocument.getElementById(\'qaNext\').onclick=()=>{pilotIndex=(pilotIndex+1)%PILOTS.length;qaDraw();pcSkip();qaDraw();};sel.onchange=qaReset;document.getElementById(\'qaDraw\').onclick=qaDraw;\ndocument.getElementById(\'qaB\').onclick=()=>{Input.injectTap(\'pad_b1\');qaDraw();};\ndocument.getElementById(\'qaDelete\').onclick=()=>{Input.injectTap(\'backspace\');qaDraw();};\ndocument.querySelector(\'#qaSpin\').onclick=()=>{stateT+=.15;qaDraw();};window.addEventListener(\'load\',qaReset);\n</script></body>\n</html>\n',encoding='utf-8')
